import { IBaseRouteObjectLine } from '../@types/routes.types';

export function mapRouteObjectToPolylineStyle(frontRouteObject: IBaseRouteObjectLine) {
  return {
    color: frontRouteObject.color,
    weight: frontRouteObject.width,
    opacity: frontRouteObject.opacity,
    dashArray: frontRouteObject.is_in_distance ? '' : '4,7',
  };
}
